export function App() {
  const [screen, setScreen] = useState<Screen>('landing')
  const [preview, setPreview] = useState<string | null>(null)
  const [session, setSession] = useState(initialGameSession)
  const moveTo = (next: Screen) => () => { setScreen(next); window.scrollTo({ top: 0, behavior: 'smooth' }) }
  const visit = (island: Island) => () => island.state === 'active' ? moveTo('hub')() : setPreview(island.name)
  return <main className={`app app--${screen}`}>
    {screen !== 'landing' && <TopBar onMap={moveTo('map')} />}
    {screen === 'landing' && <Landing onStart={moveTo('map')} />}
    {screen === 'map' && <WorldMap onIsland={visit} />}
    {screen === 'mission' && <ProjectileMission onExit={moveTo('map')} />} 
    {screen === 'hub' && <Hub onMap={moveTo('map')} onMission={moveTo('mission')} session={session} onPump={() => setSession((current) => addPump(current))} onSkill={() => setSession((current) => current.skill === 'sign-step-1' ? activateTrajectoryVision(current) : startSkillSign(current))} />}
    {preview && <LockedPreview name={preview} onClose={() => setPreview(null)} />}
  </main>
}

